[81736] = { en="Duskwood Mission VII: Recover Shadowscythe",
[=[Смерколісся, місія VII: Відновлення Тіньової Коси]=],
[=[Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів у Гниючий Сад. Знайдіть потужний артефакт, відомий як Тіньова Коса, та доставте його мені.]=],
[=[Знайдіть Тіньову Косу під час Вторгнення Кошмарів у Сутінковий Ліс нагорі у фермерському будинку в Гнилому Саду та поверніться до польового капітана Паландара.]=],
[=[У тебе є Тіньова Коса?]=],
[=[Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?]=],
},
[81737] = { en="Duskwood Mission VIII: Recover Ogre Magi text",
[=[Смерколісся, місія VIII: Відновлення тексту магів-огрів]=],
[=[Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів на Кургані Огрів Вул'гол. Знайдіть Текст Огрського Мага та доставте його мені.]=],
[=[Знайдіть Текст Мага-огра під час Вторгнення Кошмарів у Сутінковий Ліс у Кургані Огрів Вул'гол та поверніться до польового капітана Паландара.]=],
[=[У тебе є текст?]=],
[=[Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?]=],
},
[81738] = { en="Duskwood Mission IX: Recover Dragon Egg",
[=[Місія IX у Сутінковому лісі: Віднайти яйце дракона]=],
[=[Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів на ферму Йоргенів. Знайдіть невилуплене яйце Зеленого Дракона та доставте його мені.]=],
[=[Під час вторгнення Кошмарів у Сутінковий Ліс знайдіть невилуплене яйце Зеленого Дракона на фермі Йоргенів біля великого пня в полі та поверніться до польового капітана Паландара.]=],
[=[У тебе є яйце?]=],
[=[Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?]=],
},
[81739] = { en="Duskwood Mission X: Nightmare Moss",
[=[Місія X у Сутінковому лісі: Кошмарний мох]=],
[=[Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та зберіть Кошмарний Мох з-під Кошмарних Вторгнень. Ми можемо використати його магію, щоб усунути завдану шкоду. Тобі знадобиться допомога травника.]=],
[=[Зберіть 10 Кошмарного моху під час Кошмарних вторгнень у Смерколісся та поверніться до польового капітана Паландара.]=],
[=[У вас є Кошмарний Мох?]=],
[=[Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?]=],
},
[81740] = { en="Duskwood Mission XI: Cold Iron Ore",
[=[Смерколісся, місія XI: Холодна залізна руда]=],
[=[Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та зберіть Холодну Залізну Руду з-під Набігів Кошмарів. Ми можемо використати її магію, щоб повернути назад шкоду. Тобі знадобиться допомога шахтаря.]=],
[=[Зберіть 10 одиниць холодної залізної руди під час набігів Кошмарів у Сутінковому лісі та поверніться до польового капітана Паландара.]=],
[=[У вас є Холодна Залізна Руда?]=],
[=[Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?]=],
},
[81741] = { en="Duskwood Mission XII: Dream-Touched Dragonscale",
[=[Смерколісся, місія XII: Драконяча луска, доторкнута мріями]=],
[=[Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та зберіть Доторкнуту Сном Драконячу Луску у драконів у межах Вторгнення Кошмарів. Ми можемо використати її магію, щоб повернути назад шкоду. Тобі знадобиться допомога шкуродера.]=],
[=[Зберіть 10 Драконячих Лусок, Доторкнутих Сном, під час Набігів Кошмарів Смерколісся та поверніться до Польового Капітана Паландара.]=],
[=[У тебе є Луска Дракона?]=],
[=[Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?]=],
},
[81742] = { en="Duskwood Mission XIII: Defeat Ylanthrius",
[=[Місія XIII Смерколісся: Перемога над Ілантріусом]=],
[=[Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Сутінковому Гаю та вирушайте до Вторгнення Кошмарів у Садибу Йоргенів. Переможіть там дракона Ілантріуса та поверніться до мене.]=],
[=[Переможіть Ілантріуса під час вторгнення Кошмарів у Сутінковий Ліс на полі ферми Йорген та поверніться до польового капітана Паландара.]=],
nil,
[=[Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?]=],
},
[81743] = { en="Duskwood Mission XIV: Defeat Vvarc'zul",
