[81776] = { en="Ashenvale Mission IX: Recover Dream-Touched Dragonegg",
[=[Місія IX у Ясенедолі: Віднайти Драконяче Яйце, Доторкнуте Сном]=],
[=[Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та вирушайте до Вторгнення Кошмарів у Лісовій Пісні. Знайдіть Доторкнуте Сном Драконяче Яйце та доставте його мені.]=],
[=[Знайдіть Доторкнуте сном Драконяче Яйце під час Вторгнення Кошмарів Ясенеділу з центральних руїн у Лісовій Пісні та поверніть його до польового капітана Ханнали.]=],
[=[У тебе є яйце?]=],
[=[Чудово! Ваші послуги будуть щедро винагороджені. Можливо, ще одне завдання?]=],
},
[81777] = { en="Ashenvale Mission X: Dreamroot",
[=[Місія X у Ясенедолі: Корінь Снів]=],
[=[Поки ці демони відволікають нас, Смарагдовий Сон перетворюється на кошмар. Швидко, пройдіть через Портал Смарагдового Сну в Тіні Гілки та зберіть Корінь Сну з-поміж Вторгнень Кошмарів. Ми можемо використати його магію, щоб повернути назад шкоду. Тобі знадобиться допомога травника.]=],
[=[Зберіть 10 Коренів Сновидінь у Вторгненнях Кошмарів Есенвейлу та поверніться до польового капітана Ганнали.]=],
